#include <stdlib.h>
#include <string.h>
#include <linux/compat.h>

int compat_sys_mempolicy(int mode, compat_ulong_t __user *nmask, compat_ulong_t maxnode) {
    int num_bits = 0;
    compat_ulong_t *bitmap = NULL;
    size_t size = 0;

    if (maxnode == 0) {
        return -EINVAL;
    }

    if (nmask) {
        num_bits = maxnode * 8 * sizeof(compat_ulong_t);
        size = (num_bits + 7) / 8; // Calculate the number of bytes needed

        bitmap = (compat_ulong_t *)malloc(size);
        if (!bitmap) {
            return -ENOMEM;
        }

        if (copy_from_user(bitmap, nmask, size)) {
            free(bitmap);
            return -EFAULT;
        }
    }

    int result = sys_mempolicy(mode, (ulong *)bitmap, num_bits);

    if (nmask && bitmap) {
        if (copy_to_user(nmask, bitmap, size)) {
            result = -EFAULT;
        }
        free(bitmap);
    }

    return result;
}
